#!/usr/bin/env python3
import argparse, json
from pathlib import Path
import numpy as np
import scipy.sparse as sp
import scipy.sparse.linalg as sla
import scipy.sparse.csgraph as cs
from scipy.optimize import linear_sum_assignment

LX,LY=4,5
N=LX*LY
ROOT=Path("/Users/aliotaifi/Chatty/projects/j1j2/krylov_sign_structure")

# Skew torus generated by (4,0) and (1,5); both preserve checkerboard parity.
def red(x,y):
    q=y//LY
    y-=q*LY
    x-=q
    return (x%LX)+LX*y

NN=[]; NNN=[]
for y in range(LY):
    for x in range(LX):
        i=red(x,y)
        NN += [(i,red(x+1,y)),(i,red(x,y+1))]
        NNN += [(i,red(x+1,y+1)),(i,red(x+1,y-1))]
basis=np.array([s for s in range(1<<N) if s.bit_count()==N//2],dtype=np.uint32)
D=len(basis)
state_to_idx=np.full(1<<N,-1,dtype=np.int32)
state_to_idx[basis]=np.arange(D,dtype=np.int32)

def build_H(J2=.5):
    diag=np.zeros(D,float)
    rr=[]; cc=[]; vv=[]
    rows=np.arange(D,dtype=np.int32)
    for bonds,J in ((NN,1.0),(NNN,J2)):
        for u,v in bonds:
            bu=(basis>>u)&1; bv=(basis>>v)&1
            same=bu==bv
            diag += J*np.where(same,.25,-.25)
            sel=~same
            r=rows[sel]
            t=basis[sel]^(np.uint32(1<<u)|np.uint32(1<<v))
            rr.append(r); cc.append(state_to_idx[t]); vv.append(np.full(r.size,.5*J))
    rr.append(rows); cc.append(rows); vv.append(diag.copy())
    return sp.coo_matrix((np.concatenate(vv),(np.concatenate(rr),np.concatenate(cc))),
                         shape=(D,D)).tocsr(),diag
def marshall_signs():
    mask=0
    for y in range(LY):
        for x in range(LX):
            if (x+y)%2==0: mask|=1<<red(x,y)
    return np.array([1 if (int(s)&mask).bit_count()%2==0 else -1 for s in basis],dtype=np.int8)

def site_graph_dist():
    rr=[];cc=[]
    for u,v in NN+NNN:
        rr += [u,v]; cc += [v,u]
    A=sp.coo_matrix((np.ones(len(rr)),(rr,cc)),shape=(N,N)).tocsr()
    return cs.shortest_path(A,directed=False,unweighted=True)

SD=site_graph_dist()

def matching_distance(si,sj):
    a=int(basis[si]); b=int(basis[sj])
    src=[i for i in range(N) if ((b>>i)&1) and not ((a>>i)&1)]
    dst=[i for i in range(N) if ((a>>i)&1) and not ((b>>i)&1)]
    if not src: return 0
    C=SD[np.ix_(src,dst)]
    r,c=linear_sum_assignment(C)
    return int(round(float(C[r,c].sum())))
def special_columns(rng,ncols):
    neel=sum(1<<red(x,y) for y in range(LY) for x in range(LX) if (x+y)%2==0)
    stripe=sum(1<<red(x,y) for y in range(LY) for x in range(LX) if x%2==0)
    ys=[int(state_to_idx[neel]),int(state_to_idx[stripe])]
    pool=np.setdiff1d(np.arange(D),np.array(ys))
    ys += [int(z) for z in rng.choice(pool,size=ncols-len(ys),replace=False)]
    return ys

def score(G,ys,nsamp,rng):
    sm=marshall_signs(); rows=[]
    for k,y in enumerate(ys):
        g=G[:,k]; p=g*g; p/=p.sum()
        xsel=rng.choice(np.arange(D),size=nsamp,replace=True,p=p)
        true=np.where(g[xsel]>=0,1,-1)
        pred=np.array([1 if matching_distance(int(x),y)%2==0 else -1 for x in xsel],dtype=np.int8)
        base=sm[xsel]*sm[y]
        rows.append({"y":int(y),
                     "matching_error":float(np.mean(pred!=true)),
                     "marshall_error":float(np.mean(base!=true))})
    return rows
def main():
    ap=argparse.ArgumentParser()
    ap.add_argument("--ncols",type=int,default=4)
    ap.add_argument("--nsamp",type=int,default=5000)
    ap.add_argument("--seed",type=int,default=20260930)
    ap.add_argument("--out",default=str(ROOT/"results/finite_tau_matching_20site_exact.json"))
    args=ap.parse_args()
    rng=np.random.default_rng(args.seed)
    print("D",D,"building H",flush=True)
    H,_=build_H(.5)
    print("H nnz",H.nnz,flush=True)
    ys=special_columns(rng,args.ncols)
    E=np.zeros((D,args.ncols)); E[ys,np.arange(args.ncols)]=1.0

    out={"geometry":"20-site skew torus T=(4,0),(1,5)","D":D,"ys":ys,"times":{}}
    for tau in (0.25,0.5):
        print("tau",tau,flush=True)
        G=np.asarray(sla.expm_multiply(-tau*H,E),float)
        G/=np.linalg.norm(G,axis=0,keepdims=True)
        rows=score(G,ys,args.nsamp,rng)
        out["times"][str(tau)]={"rows":rows,
            "matching_mean":float(np.mean([r["matching_error"] for r in rows])),
            "marshall_mean":float(np.mean([r["marshall_error"] for r in rows]))}
        print(out["times"][str(tau)],flush=True)
    Path(args.out).write_text(json.dumps(out,indent=2))
    print("WROTE",args.out,flush=True)

if __name__=="__main__":
    main()
